{
    "name": "058_moe_expert_token_radix_sort_with_prefix_sum",
    "hf_id": "inclusionAI/Ling-mini-2.0",
    "description": "MoE token sorting and bucketing using radix sort with prefix sum. Performs O(N) counting sort on bounded expert indices (0-255), computes prefix sum for cumulative offsets, and returns sorted token indices and expert boundaries. Critical for efficient MoE token-to-expert routing.",
    "axes": {
        "batch_size": {
            "type": "var",
            "description": "Batch size"
        },
        "seq_len": {
            "type": "var",
            "description": "Sequence length"
        },
        "num_experts": {
            "type": "const",
            "value": 256,
            "description": "Total number of experts"
        },
        "num_experts_per_tok": {
            "type": "const",
            "value": 8,
            "description": "Number of experts selected per token"
        },
        "num_tokens": {
            "type": "expr",
            "expression": "batch_size * seq_len * num_experts_per_tok",
            "description": "Total number of token-expert assignments"
        },
        "num_experts_plus_one": {
            "type": "expr",
            "expression": "num_experts + 1",
            "description": "Size of expert offsets array"
        }
    },
    "custom_inputs_entrypoint": "get_inputs",
    "inputs": {
        "topk_idx": {
            "shape": [
                "batch_size",
                "seq_len",
                "num_experts_per_tok"
            ],
            "dtype": "int32",
            "description": "Expert indices for each token, values in [0, num_experts-1]"
        }
    },
    "outputs": {
        "sorted_token_indices": {
            "shape": [
                "num_tokens"
            ],
            "dtype": "int32",
            "description": "Token indices sorted by expert assignment"
        },
        "expert_offsets": {
            "shape": [
                "num_experts_plus_one"
            ],
            "dtype": "int32",
            "description": "Cumulative offsets for expert boundaries, expert_offsets[i]:expert_offsets[i+1] gives token range for expert i"
        }
    },
    "reference": "import torch\n\n\ndef get_inputs(\n    axes_and_scalars: dict[str, ...], device: torch.device\n) -> dict[str, torch.Tensor]:\n    \"\"\"Generate inputs with valid expert indices in range [0, num_experts-1].\"\"\"\n    batch_size = axes_and_scalars[\"batch_size\"]\n    seq_len = axes_and_scalars[\"seq_len\"]\n    num_experts = axes_and_scalars[\"num_experts\"]\n    num_experts_per_tok = axes_and_scalars[\"num_experts_per_tok\"]\n    \n    # Generate random expert indices in valid range [0, num_experts-1]\n    topk_idx = torch.randint(\n        0, num_experts,\n        (batch_size, seq_len, num_experts_per_tok),\n        dtype=torch.int32,\n        device=device\n    )\n    \n    return {\"topk_idx\": topk_idx}\n\n\n@torch.no_grad()\ndef run(topk_idx: torch.Tensor):\n    \"\"\"\n    MoE token sorting using counting sort with prefix sum.\n    \n    Args:\n        topk_idx: Expert indices (batch_size, seq_len, num_experts_per_tok)\n                 with values in [0, num_experts-1]\n    \n    Returns:\n        sorted_token_indices: Token indices sorted by expert (num_tokens,)\n        expert_offsets: Cumulative offsets (num_experts+1,)\n    \"\"\"\n    num_experts = 256\n    flat = topk_idx.reshape(-1)\n\n    # Stable sort on expert IDs = counting sort permutation\n    _, sorted_token_indices = flat.sort(stable=True)\n\n    # Expert offsets via histogram + prefix sum\n    expert_offsets = torch.zeros(num_experts + 1, dtype=torch.int32, device=flat.device)\n    expert_offsets[1:] = torch.bincount(flat.long(), minlength=num_experts).cumsum(0).to(torch.int32)\n\n    return sorted_token_indices.to(torch.int32), expert_offsets\n"
}

